"""
household-tracker.py - Simple CLI tool for tracking household expenses.

Usage:
  python household-tracker.py add --date YYYY-MM-DD --category <cat> --amount <num> [--desc "text"]
  python household-tracker.py view --by date|category [--from YYYY-MM-DD] [--to YYYY-MM-DD]
  python household-tracker.py summary --by category
  python household-tracker.py export --format csv
"""

import argparse
import json
import csv
from datetime import datetime
import os

DATA_FILE = "expenses.json"

def load_expenses():
    if not os.path.exists(DATA_FILE):
        return []
    try:
        with open(DATA_FILE, 'r') as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError):
        return []

def save_expenses(expenses):
    with open(DATA_FILE, 'w') as f:
        json.dump(expenses, f, indent=2)

def validate_date(date_str):
    try:
        datetime.strptime(date_str, "%Y-%m-%d")
        return True
    except ValueError:
        return False

def validate_amount(amount_str):
    try:
        amount = float(amount_str)
        return amount >= 0
    except ValueError:
        return False

def add_entry(args):
    if not validate_date(args.date):
        print("Invalid date format. Use YYYY-MM-DD.")
        return
    if not validate_amount(args.amount):
        print("Amount must be a non-negative number.")
        return
    expense = {
        "date": args.date,
        "category": args.category,
        "amount": float(args.amount),
        "description": args.desc or ""
    }
    expenses = load_expenses()
    expenses.append(expense)
    save_expenses(expenses)
    print(f"Added: {args.amount} in {args.category} on {args.date}")

