def summary_by_category(args):
    expenses = load_expenses()
    if not expenses:
        print("No expenses to summarize.")
        return

    totals = {}
    for exp in expenses:
        cat = exp["category"]
        totals[cat] = totals.get(cat, 0) + exp["amount"]

    print("Spending Summary by Category:")
    for cat, total in sorted(totals.items()):
        print(f"{cat.capitalize()}: ${total:.2f}")

